arguments.file_text:
@using sv_25b375b8cdda431ca8bd04b95acf0829.Models

<nav class="step-indicator" aria-label="Application progress">
    <ol>
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var step = i + 1;
            var status = step == CurrentStep ? "active"
                       : CompletedSteps.Contains(step) ? "completed"
                       : "upcoming";
            var clickable = CompletedSteps.Contains(step) && step != CurrentStep;

            <li class="step @status" @onclick="() => HandleClick(step)"
                role="@(clickable ? "button" : null)"
                tabindex="@(clickable ? 0 : -1)"
                aria-current="@(step == CurrentStep ? "step" : null)">
                <span class="step-number">
                    @if (CompletedSteps.Contains(step) && step != CurrentStep)
                    {
                        <span class="checkmark">✓</span>
                    }
                    else
                    {
                        @step
                    }
                </span>
                <span class="step-label">@StepNames[i]</span>
            </li>
        }
    </ol>
</nav>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter, EditorRequired] public EventCallback<int> OnStepClicked { get; set; }

    private static readonly string[] StepNames =
        ["Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"];

    private async Task HandleClick(int step)
    {
        if (CompletedSteps.Contains(step) && step != CurrentStep)
        {
            await OnStepClicked.InvokeAsync(step);
        }
    }
}

nav.step-indicator ol {
    display: flex;
    list-style: none;
    padding: 0;
    margin: 0 0 2rem;
    gap: 0.25rem;
}

nav.step-indicator li.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    flex: 1;
    position: relative;
    text-align: center;
}

nav.step-indicator li.step::after {
    content: "";
    position: absolute;
    top: 18px;
    left: 55%;
    width: 90%;
    height: 2px;
    background: #d1d5db;
    z-index: 0;
}

nav.step-indicator li.step:last-child::after {
    display: none;
}

nav.step-indicator li.completed::after {
    background: #2563eb;
}

.step-number {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
    font-size: 0.875rem;
    z-index: 1;
    background: #e5e7eb;
    color: #9ca3af;
    border: 2px solid #e5e7eb;
    transition: all 0.2s;
}

li.active .step-number {
    background: #2563eb;
    color: white;
    border-color: #2563eb;
}

li.completed .step-number {
    background: #2563eb;
    color: white;
    border-color: #2563eb;
}

li.completed {
    cursor: pointer;
}

li.completed:hover .step-number {
    background: #1d4ed8;
    border-color: #1d4ed8;
}

