<nav class="step-indicator" aria-label="Application progress">
    <ol>
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var step = i + 1;
            var status = step == CurrentStep ? "active"
                       : CompletedSteps.Contains(step) ? "completed"
                       : "upcoming";
            var clickable = CompletedSteps.Contains(step) && step != CurrentStep;

            <li class="step @status" @onclick="() => HandleClick(step)"
                role="@(clickable ? "button" : null)"
                tabindex="@(clickable ? 0 : -1)"
                aria-current="@(step == CurrentStep ? "step" : null)">
                <span class="step-number">
                    @if (CompletedSteps.Contains(step) && step != CurrentStep)
                    {
                        <span class="checkmark">✓</span>
                    }
                    else
                    {
                        @step
                    }
                </span>
                <span class="step-label">@StepNames[i]</span>
            </li>
        }
    </ol>
</nav>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
