@using sv_25b375b8cdda431ca8bd04b95acf0829.Models
@inject IApplicationService ApplicationService

<div class="step-content">
    <h2>Personal Information</h2>

    <div class="form-group">
        <label>Full Name *</label>
        <input type="text" @bind="Model.FullName" @bind:event="oninput" placeholder="Your full name" />
    </div>

    <div class="form-group">
        <label>Email Address *</label>
        <input type="email" @bind="Model.Email" @bind:event="oninput" placeholder="email@example.com" />
        @if (!string.IsNullOrEmpty(_emailError))
        {
            <span class="field-error">@_emailError</span>
        }
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Phone *</label>
            <input type="tel" @bind="Model.Phone" @bind:event="oninput" placeholder="Phone number" />
        </div>
        <div class="form-group">
            <label>Address *</label>
            <input type="text" @bind="Model.Address" @bind:event="oninput" placeholder="Your address" />
        </div>
    </div>

    @if (_errors.Count > 0)
    {
        <div class="validation-summary">
            @foreach (var error in _errors)
            {
                <p>@error</p>
            }
        </div>
    }

    <div class="step-actions">
        <span></span>
        <button type="button" class="btn-primary" @onclick="HandleNext" disabled="@_isValidating">
            @if (_isValidating)
            {
                <span>Validating…</span>
            }
            else
            {
                <span>Next →</span>
            }
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Model { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }

    private List<string> _errors = new();
    private string? _emailError;
    private bool _isValidating;

    private async Task HandleNext()
    {
        _errors.Clear();
        _emailError = null;

        if (string.IsNullOrWhiteSpace(Model.FullName))
            _errors.Add("Full name is required.");
        if (string.IsNullOrWhiteSpace(Model.Email))
            _errors.Add("Email is required.");
        if (string.IsNullOrWhiteSpace(Model.Phone))
            _errors.Add("Phone is required.");
        if (string.IsNullOrWhiteSpace(Model.Address))
            _errors.Add("Address is required.");

        if (_errors.Count > 0) return;

        _isValidating = true;
        try
        {
            var isValid = await ApplicationService.ValidateEmailAsync(Model.Email);
            if (!isValid)
            {
                _emailError = "This email address is not valid.";
                return;
            }
        }
        finally
        {
            _isValidating = false;
        }

        await OnNext.InvokeAsync();
    }
}

@using sv_25b375b8cdda431ca8bd04b95acf0829.Models

<div class="step-content">
    <h2>Work History</h2>

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        <WorkEntryForm Entry="Entries[index]"
                       Index="index"
                       CanRemove="Entries.Count > 1"
                       OnRemove="() => RemoveEntry(index)" />
    }

    <button type="button" class="btn-secondary" @onclick="AddEntry">
        + Add Another Position
    </button>

    @if (_errors.Count > 0)
    {
        <div class="validation-summary">
            @foreach (var error in _errors)
            {
                <p>@error</p>
            }
        </div>
    }

    <div class="step-actions">
        <button type="button" class="btn-outline" @onclick="OnBack">← Back</button>
        <button type="button" class="btn-primary" @onclick="HandleNext">Next →</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<WorkEntryModel> Entries { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private List<string> _errors = new();

    private void AddEntry()
    {
        Entries.Add(new WorkEntryModel());
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
            Entries.RemoveAt(index);
    }

    private async Task HandleNext()
    {
        _errors.Clear();

        for (int i = 0; i < Entries.Count; i++)
        {
            var e = Entries[i];
            if (string.IsNullOrWhiteSpace(e.Company))
                _errors.Add($"Position {i + 1}: Company name is required.");
            if (string.IsNullOrWhiteSpace(e.Title))
                _errors.Add($"Position {i + 1}: Job title is required.");
            if (e.StartDate is null)
                _errors.Add($"Position {i + 1}: Start date is required.");
        }

        if (_errors.Count == 0)
            await OnNext.InvokeAsync();
    }
}

@using sv_25b375b8cdda431ca8bd04b95acf0829.Models

<div class="step-content">
    <h2>References</h2>
    <p class="step-description">Please provide 2–3 professional references.</p>

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        <ReferenceForm Reference="References[index]"
                       Index="index"
                       CanRemove="References.Count > 2"
                       OnRemove="() => RemoveReference(index)" />
    }

    @if (References.Count < 3)
    {
        <button type="button" class="btn-secondary" @onclick="AddReference">
            + Add Reference
        </button>
    }

    @if (_errors.Count > 0)
    {
        <div class="validation-summary">
            @foreach (var error in _errors)
            {
                <p>@error</p>
            }
        </div>
    }

    <div class="step-actions">
        <button type="button" class="btn-outline" @onclick="OnBack">← Back</button>
        <button type="button" class="btn-primary" @onclick="HandleNext">Next →</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private List<string> _errors = new();

    private void AddReference()
    {
        if (References.Count < 3)
            References.Add(new ReferenceModel());
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2)
            References.RemoveAt(index);
    }

    private async Task HandleNext()
    {
        _errors.Clear();

        for (int i = 0; i < References.Count; i++)
        {
            var r = References[i];
            if (string.IsNullOrWhiteSpace(r.Name))
                _errors.Add($"Reference {i + 1}: Name is required.");
            if (string.IsNullOrWhiteSpace(r.Relationship))
                _errors.Add($"Reference {i + 1}: Relationship is required.");
            if (string.IsNullOrWhiteSpace(r.Email))
                _errors.Add($"Reference {i + 1}: Email is required.");
            if (string.IsNullOrWhiteSpace(r.Phone))
                _errors.Add($"Reference {i + 1}: Phone is required.");
        }

        if (_errors.Count == 0)
            await OnNext.InvokeAsync();
    }
}

@using sv_25b375b8cdda431ca8bd04b95acf0829.Models

<div class="step-content">
    <h2>Review & Submit</h2>
    <p class="step-description">Please review your application before submitting.</p>

    @if (_submitted)
    {
        <div class="confirmation">
            <div class="confirmation-icon">✓</div>
            <h3>Application Submitted!</h3>
            <p>Your application has been received. Your application ID is:</p>
            <p class="application-id">#@_applicationId</p>
        </div>
    }
    else
    {
        <section class="review-section">
            <div class="review-header">
                <h3>Personal Information</h3>
                <button type="button" class="btn-link" @onclick="() => OnEditStep.InvokeAsync(1)">Edit</button>
            </div>
            <dl>
                <dt>Full Name</dt><dd>@Personal.FullName</dd>
                <dt>Email</dt><dd>@Personal.Email</dd>
                <dt>Phone</dt><dd>@Personal.Phone</dd>
                <dt>Address</dt><dd>@Personal.Address</dd>
            </dl>
        </section>

        <section class="review-section">
            <div class="review-header">
                <h3>Work History</h3>
                <button type="button" class="btn-link" @onclick="() => OnEditStep.InvokeAsync(2)">Edit</button>
            </div>
            @foreach (var entry in WorkEntries)
            {
                <div class="review-work-entry">
                    <strong>@entry.Title</strong> at <strong>@entry.Company</strong>
                    <br />
                    <span class="date-range">
                        @entry.StartDate?.ToString("MMM yyyy") –
                        @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                    </span>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <p class="review-description">@entry.Description</p>
                    }
                </div>
            }
        </section>

        <section class="review-section">
            <div class="review-header">
                <h3>References</h3>
                <button type="button" class="btn-link" @onclick="() => OnEditStep.InvokeAsync(3)">Edit</button>
            </div>
            @foreach (var r in References)
            {
                <div class="review-reference">
                    <strong>@r.Name</strong> — @r.Relationship
                    <br />
                    <span>@r.Email · @r.Phone</span>
                </div>
            }
        </section>

        <section class="review-section">
            <div class="review-header">
                <h3>Cover Letter</h3>
                <button type="button" class="btn-link" @onclick="() => OnEditStep.InvokeAsync(4)">Edit</button>
            </div>
            <p class="review-cover-letter">@CoverLetter</p>
        </section>

        @if (!string.IsNullOrEmpty(_error))
        {
            <div class="validation-summary">
                <p>@_error</p>
            </div>
        }

        <div class="step-actions">
            <button type="button" class="btn-outline" @onclick="OnBack">← Back</button>
            <button type="button" class="btn-primary btn-submit" @onclick="HandleSubmit" disabled="@_submitting">
                @if (_submitting)
                {
                    <span>Submitting…</span>
                }
                else
                {
                    <span>Submit Application</span>
                }
            </button>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Personal { get; set; } = default!;
    [Parameter, EditorRequired] public List<WorkEntryModel> WorkEntries { get; set; } = default!;
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = default!;
    [Parameter, EditorRequired] public string CoverLetter { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback<int> OnEditStep { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }
    [Parameter, EditorRequired] public EventCallback OnSubmit { get; set; }

    // Set by the parent after submission
    [Parameter] public int? ApplicationId { get; set; }

    private bool _submitting;
    private bool _submitted;
    private int _applicationId;
    private string? _error;

    protected override void OnParametersSet()
    {
        if (ApplicationId.HasValue)
        {
            _submitted = true;
            _applicationId = ApplicationId.Value;
        }
    }

    private async Task HandleSubmit()
    {
        _error = null;
        _submitting = true;

        try
        {
            await OnSubmit.InvokeAsync();
        }
        catch (Exception)
        {
            _error = "An error occurred while submitting. Please try again.";
        }
        finally
        {
            _submitting = false;
        }
    }
}

