toolArgs.file_text:
.apply-page {
    max-width: 760px;
    margin: 0 auto;
    padding: 2rem 1rem;
}

.apply-page h1 {
    text-align: center;
    margin-bottom: 2rem;
    font-size: 1.75rem;
    color: #111827;
}

/* Step content area */
::deep .step-content {
    background: #fff;
    border: 1px solid #e5e7eb;
    border-radius: 8px;
    padding: 2rem;
}

::deep .step-content h2 {
    margin: 0 0 0.25rem;
    font-size: 1.35rem;
    color: #111827;
}

::deep .step-description {
    color: #6b7280;
    margin: 0 0 1.5rem;
}

/* Form elements */
::deep .form-group {
    margin-bottom: 1rem;
}

::deep .form-group label {
    display: block;
    font-weight: 500;
    margin-bottom: 0.25rem;
    font-size: 0.875rem;
    color: #374151;
}

::deep .form-group input[type="text"],
::deep .form-group input[type="email"],
::deep .form-group input[type="tel"],
::deep .form-group input[type="date"],
::deep .form-group textarea {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #d1d5db;
    border-radius: 6px;
    font-size: 0.9rem;
    transition: border-color 0.15s;
    box-sizing: border-box;
}

::deep .form-group input:focus,
::deep .form-group textarea:focus {
    outline: none;
    border-color: #2563eb;
    box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.1);
}

::deep .form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

/* Fieldset styling */
::deep fieldset {
    border: 1px solid #e5e7eb;
    border-radius: 6px;
    padding: 1.25rem;
    margin-bottom: 1rem;
    position: relative;
}

::deep fieldset legend {
    font-weight: 600;
    font-size: 0.95rem;
    padding: 0 0.5rem;
    color: #374151;
}

/* Buttons */
::deep .step-actions {
    display: flex;
    justify-content: space-between;
    margin-top: 1.5rem;
    padding-top: 1.5rem;
    border-top: 1px solid #e5e7eb;
}

::deep .btn-primary {
    background: #2563eb;
    color: #fff;
    border: none;
    padding: 0.6rem 1.5rem;
    border-radius: 6px;
    font-weight: 600;
    cursor: pointer;
    font-size: 0.9rem;
    transition: background 0.15s;
}

::deep .btn-primary:hover:not(:disabled) {
    background: #1d4ed8;
}

::deep .btn-primary:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

::deep .btn-outline {
    background: #fff;
    color: #374151;
    border: 1px solid #d1d5db;
    padding: 0.6rem 1.5rem;
    border-radius: 6px;
    font-weight: 500;
    cursor: pointer;
    font-size: 0.9rem;
    transition: background 0.15s;
}

::deep .btn-outline:hover {
    background: #f9fafb;
}

::deep .btn-secondary {
    background: #f3f4f6;
    color: #374151;
    border: 1px solid #d1d5db;
    padding: 0.5rem 1rem;
    border-radius: 6px;
    font-weight: 500;
    cursor: pointer;
    font-size: 0.85rem;
    margin-bottom: 1rem;
}

::deep .btn-secondary:hover {
    background: #e5e7eb;
}

::deep .btn-remove {
    background: none;
    border: none;
    color: #dc2626;
    cursor: pointer;
    font-size: 0.8rem;
    font-weight: 500;
    float: right;
}

::deep .btn-remove:hover {
    color: #991b1b;
}

::deep .btn-link {
    background: none;
    border: none;
    color: #2563eb;
    cursor: pointer;
    font-weight: 500;
    font-size: 0.85rem;
    text-decoration: underline;
}

::deep .btn-link:hover {
    color: #1d4ed8;
}

::deep .btn-submit {
    padding: 0.75rem 2rem;
    font-size: 1rem;
}

/* Validation */
::deep .validation-summary {
    background: #fef2f2;
    border: 1px solid #fecaca;
    border-radius: 6px;
    padding: 0.75rem 1rem;
    margin-top: 1rem;
}

::deep .validation-summary p {
    margin: 0.25rem 0;
    color: #dc2626;
    font-size: 0.85rem;
}

::deep .field-error {
    color: #dc2626;
    font-size: 0.8rem;
    margin-top: 0.25rem;
    display: block;
}

/* Character count */
::deep .char-count {
    display: block;
    text-align: right;
    font-size: 0.8rem;
    color: #6b7280;
    margin-top: 0.25rem;
}

::deep .char-count.over-limit {
    color: #dc2626;
    font-weight: 600;
}

/* Review section */
::deep .review-section {
    border: 1px solid #e5e7eb;
    border-radius: 6px;
    padding: 1.25rem;
    margin-bottom: 1rem;
}

::deep .review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

::deep .review-header h3 {
    margin: 0;
    font-size: 1rem;
    color: #111827;
}

::deep .review-section dl {
    display: grid;
    grid-template-columns: 120px 1fr;
    gap: 0.35rem 1rem;
    margin: 0;
}

::deep .review-section dt {
    font-weight: 500;
    color: #6b7280;
    font-size: 0.85rem;
}

::deep .review-section dd {
    margin: 0;
    font-size: 0.9rem;
    color: #111827;
}

::deep .review-work-entry {
    padding: 0.5rem 0;
    border-bottom: 1px solid #f3f4f6;
}

::deep .review-work-entry:last-child {
    border-bottom: none;
}

::deep .date-range {
    font-size: 0.8rem;
    color: #6b7280;
}

::deep .review-description {
    font-size: 0.85rem;
    color: #4b5563;
    margin: 0.25rem 0 0;
}

::deep .review-reference {
    padding: 0.5rem 0;
    border-bottom: 1px solid #f3f4f6;
    font-size: 0.9rem;
}

::deep .review-reference:last-child {
    border-bottom: none;
}

::deep .review-cover-letter {
    white-space: pre-wrap;
    font-size: 0.9rem;
    color: #374151;
    margin: 0;
}

/* Confirmation */
::deep .confirmation {
    text-align: center;
    padding: 3rem 1rem;
}

::deep .confirmation-icon {
    width: 64px;
    height: 64px;
    border-radius: 50%;
    background: #10b981;
    color: #fff;
    font-size: 2rem;
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 0 auto 1rem;
}

::deep .confirmation h3 {
    font-size: 1.5rem;
    color: #111827;
    margin: 0 0 0.5rem;
}

::deep .application-id {
    font-size: 1.75rem;
    font-weight: 700;
    color: #2563eb;
}

